SELECT 
FROM fund_plan_adjustment
WHERE approval_status = 'APPROVED' AND org_id = #{orgId} AND is_deleted = 0

    AND approve_time >= #{startDate}


    AND approve_time <= #{endDate}

ORDER BY approve_time DESC

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN approval_status = 'PENDING' THEN 1 END) as pendingCount, COUNT(CASE WHEN approval_status = 'APPROVED' THEN 1 END) as approvedCount, COUNT(CASE WHEN approval_status = 'REJECTED' THEN 1 END) as rejectedCount, COALESCE(SUM(ABS(adjustment_amount)), 0) as totalAdjustmentAmount, COALESCE(AVG(ABS(adjustment_amount)), 0) as avgAdjustmentAmount, COUNT(CASE WHEN ABS(adjustment_amount) >= 100000 THEN 1 END) as highImpactCount FROM fund_plan_adjustment WHERE is_deleted = 0
AND org_id = #{orgId}
AND plan_id = #{planId}
AND adjustment_type = #{adjustmentType}
AND approval_status = #{approvalStatus}

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as adjustmentCount, COUNT(CASE WHEN approval_status = 'APPROVED' THEN 1 END) as approvedCount, COALESCE(SUM(ABS(adjustment_amount)), 0) as totalAdjustmentAmount, COALESCE(AVG(ABS(adjustment_amount)), 0) as avgAdjustmentAmount FROM fund_plan_adjustment WHERE org_id = #{orgId} AND is_deleted = 0
AND adjustment_type = #{adjustmentType}
AND create_time >= DATE_SUB(CURDATE(), INTERVAL #{months} MONTH) GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC

