UPDATE fund_plan_adjustment SET approval_status = 'APPROVED', approve_user = #{approveUser}, approve_time = NOW(), approve_comment = #{approveComment}, update_user = #{approveUser}, update_time = NOW() WHERE adjustment_id IN
#{adjustmentId}
AND approval_status = 'PENDING' AND is_deleted = 0

UPDATE fund_plan_adjustment SET approval_status = 'REJECTED', approve_user = #{rejectUser}, approve_time = NOW(), approve_comment = #{rejectReason}, update_user = #{rejectUser}, update_time = NOW() WHERE adjustment_id IN
#{adjustmentId}
AND approval_status = 'PENDING' AND is_deleted = 0
